INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100', 'MATH.G2.NUMBER.NUMBER_CONCEPT', 'mathematics', 2, 'Identify numbers 1 to 100 in symbols', ARRAY['MATH.G2.NUMBER.NUMBER_CONCEPT.a', 'MATH.G2.NUMBER.NUMBER_CONCEPT.c']::text[], 'The child picks out and names any number from 1 to 100 shown on a card, chart, page or calendar, and tells apart numbers with the same digits (16 and 61). Number games with cards or devices are played in class.', '["point to the number said","name the number on the card","which card shows 47","find the number on a hundred chart"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100', 'MATH.G2.NUMBER.NUMBER_CONCEPT', 'mathematics', 2, 'Represent numbers 1 to 100 using concrete objects', ARRAY['MATH.G2.NUMBER.NUMBER_CONCEPT.b']::text[], 'The child shows a number up to 100 with real objects grouped in tens and ones (bundles of 10 sticks and loose sticks), counts a collection by making tens, and matches a group of objects to its number.', '["how many sticks are shown","show this number with bundles","match the group to its number","count by making tens"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100', 'MATH.G2.NUMBER.WHOLE_NUMBERS', 'mathematics', 2, 'Count forward up to 100 from any point', ARRAY['MATH.G2.NUMBER.WHOLE_NUMBERS.a']::text[], 'Starting from any number, the child counts on in ones to 100, crossing each ten correctly (29, 30, 31; 99, 100), and says the next number after any number below 100.', '["count on from a number","what comes next","missing number in a forward count","count on across a ten"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_BACK_50', 'MATH.G2.NUMBER.WHOLE_NUMBERS', 'mathematics', 2, 'Count backward from 50', ARRAY['MATH.G2.NUMBER.WHOLE_NUMBERS.b']::text[], 'The child counts back in ones from 50, or from any number up to 50, crossing each ten correctly (31, 30, 29), and says the number before a given number.', '["count back from a number","what comes before","missing number in a backward count","count back across a ten"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.READ_WRITE_SYMBOLS_100', 'MATH.G2.NUMBER.WHOLE_NUMBERS', 'mathematics', 2, 'Read and write numbers 1 to 100 in symbols', ARRAY['MATH.G2.NUMBER.WHOLE_NUMBERS.c']::text[], 'The child writes in symbols any number up to 100 that is said or shown, with the digits in the right order and correctly formed (not mirror-written), and reads a written number aloud.', '["write the number said","read the number","write the number shown by objects","correct a mirrored digit"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.PLACE_VALUE_TENS', 'MATH.G2.NUMBER.WHOLE_NUMBERS', 'mathematics', 2, 'Identify the place value of digits in ones and tens', ARRAY['MATH.G2.NUMBER.WHOLE_NUMBERS.d']::text[], 'For any 2-digit number the child says which digit is in the tens place and which in the ones place, what each is worth (the 7 in 74 is 70), and builds a number from tens and ones (5 tens and 3 ones is 53).', '["which digit is in the tens place","what is the digit worth","tens and ones to a number","put the card in the right tin"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G2_PLACE_VALUE']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.WORDS_20', 'MATH.G2.NUMBER.WHOLE_NUMBERS', 'mathematics', 2, 'Read and write numbers 1 to 20 in words', ARRAY['MATH.G2.NUMBER.WHOLE_NUMBERS.e']::text[], 'The child reads and writes the number words one to twenty with correct spelling (eight, eleven, twelve, fifteen, twenty) and matches a word to its number.', '["write the number in words","match the word to the number","choose the correct spelling","read the word"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.PATTERNS_100', 'MATH.G2.NUMBER.WHOLE_NUMBERS', 'mathematics', 2, 'Missing numbers in number patterns up to 100', ARRAY['MATH.G2.NUMBER.WHOLE_NUMBERS.f']::text[], 'The child finds the rule of a pattern counting on or back in ones, twos, fives or tens (35, 40, 45, __), and fills in missing numbers up to 100.', '["next number in the pattern","missing number in the middle","what is the jump","count in fives or tens"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G2_COUNTING']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.ADDITION.ADD_2D_1D', 'MATH.G2.NUMBER.ADDITION', 'mathematics', 2, 'Add a 2-digit number and a 1-digit number, without and with regrouping', ARRAY['MATH.G2.NUMBER.ADDITION.a']::text[], 'The child adds a 1-digit number to a 2-digit number with a sum up to 100 (43 + 5 = 48; 47 + 8 = 55), counting on or in a column, and carries a ten when the ones make ten or more.', '["column addition","horizontal to vertical","count on","a story with a total"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.ADDITION.ADD_2D_2D', 'MATH.G2.NUMBER.ADDITION', 'mathematics', 2, 'Add two 2-digit numbers, without and with regrouping', ARRAY['MATH.G2.NUMBER.ADDITION.b']::text[], 'The child adds two 2-digit numbers with a sum up to 100 (34 + 25 = 59; 38 + 45 = 83), lining up tens and ones and carrying a ten from the ones.', '["column addition","horizontal addition","a two-amount story","missing digit"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.ADDITION.ADD_TENS', 'MATH.G2.NUMBER.ADDITION', 'mathematics', 2, 'Add two multiples of 10 with a sum up to 100', ARRAY['MATH.G2.NUMBER.ADDITION.c']::text[], 'The child adds two multiples of ten (30 + 50 = 80) by adding the tens, and explains it with bundles of ten.', '["add the tens","bundles of ten","ten-shilling coins","missing ten"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G2_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.ADDITION.ADD_MISSING_100', 'MATH.G2.NUMBER.ADDITION', 'mathematics', 2, 'Missing numbers in addition and addition patterns up to 100', ARRAY['MATH.G2.NUMBER.ADDITION.d']::text[], 'The child finds the missing number in an addition (35 + __ = 100) by counting up in tens and ones, and continues or fills in a pattern made by adding the same number (12, 17, 22, __).', '["missing number in an addition","how much more to make 100","next in an adding pattern","missing term"]'::jsonb, '["reasoning","procedure"]'::jsonb, ARRAY['G2_ADD']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.SUBTRACTION.SUB_2D_1D', 'MATH.G2.NUMBER.SUBTRACTION', 'mathematics', 2, 'Subtract a 1-digit number from a 2-digit number without regrouping', ARRAY['MATH.G2.NUMBER.SUBTRACTION.a']::text[], 'The child subtracts a 1-digit number from a 2-digit number where the ones digit is big enough (48 - 5 = 43), by counting back or in a column.', '["column subtraction","count back","how many are left","horizontal to vertical"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.SUBTRACTION.SUB_2D_2D', 'MATH.G2.NUMBER.SUBTRACTION', 'mathematics', 2, 'Subtract a 2-digit number from a 2-digit number, without and with regrouping', ARRAY['MATH.G2.NUMBER.SUBTRACTION.b']::text[], 'The child subtracts two 2-digit numbers (68 - 25 = 43; 52 - 27 = 25), opening a ten into ten ones when the top ones digit is smaller, using place value apparatus or a column.', '["column subtraction","how many fewer","how many are left","find the mistake"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.SUBTRACTION.SUB_TENS', 'MATH.G2.NUMBER.SUBTRACTION', 'mathematics', 2, 'Subtract a lower multiple of 10 from a higher multiple of 10', ARRAY['MATH.G2.NUMBER.SUBTRACTION.c']::text[], 'The child subtracts multiples of ten (80 - 30 = 50) by taking tens from tens, and explains it with bundles.', '["take away tens","bundles of ten","ten-shilling coins","missing ten"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G2_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.SUBTRACTION.SUB_PATTERNS_100', 'MATH.G2.NUMBER.SUBTRACTION', 'mathematics', 2, 'Missing numbers in patterns involving subtraction up to 100', ARRAY['MATH.G2.NUMBER.SUBTRACTION.d']::text[], 'The child continues or fills in a pattern made by taking away the same number (90, 80, 70, __; 50, 47, 44, __) and finds a missing number in a subtraction sentence (60 - __ = 25).', '["next number going down","missing term","what is taken away","missing number in a subtraction"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G2_SUB']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.MULTIPLICATION.MULT_REPEATED_ADD', 'MATH.G2.NUMBER.MULTIPLICATION', 'mathematics', 2, 'Represent multiplication as repeated addition of twos and threes', ARRAY['MATH.G2.NUMBER.MULTIPLICATION.a']::text[], 'The child shows 1, 2 or 3 groups of 2 or 3 with counters and writes the repeated addition (3 + 3 = 6), saying how many groups and how many in each.', '["make groups with counters","write the repeated addition","how many groups of","draw the groups"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G2_MULTIPLY_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.MULTIPLICATION.MULT_SIGN', 'MATH.G2.NUMBER.MULTIPLICATION', 'mathematics', 2, 'Write repeated addition as multiplication using the x sign', ARRAY['MATH.G2.NUMBER.MULTIPLICATION.b']::text[], 'The child writes a repeated addition as a multiplication sentence (2 + 2 + 2 = 6 is 3 x 2 = 6), with the number of groups and the size of a group, and reads x as ''times'' or ''groups of''.', '["write as multiplication","read the x sentence","match addition to multiplication","fill the missing number"]'::jsonb, '["representation"]'::jsonb, ARRAY['G2_MULTIPLY_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.MULTIPLICATION.MULT_BY_1_TO_5', 'MATH.G2.NUMBER.MULTIPLICATION', 'mathematics', 2, 'Multiply 1-digit numbers by 1, 2, 3, 4 and 5', ARRAY['MATH.G2.NUMBER.MULTIPLICATION.c']::text[], 'The child gives products of a 1-digit number and 1, 2, 3, 4 or 5 (4 x 5 = 20), by skip counting or from a multiplication chart, and solves equal-groups stories (legs, rows, packets).', '["times fact","equal groups story","skip count","read the chart"]'::jsonb, '["recall","procedure"]'::jsonb, ARRAY['G2_MULTIPLY_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.MULTIPLICATION.MULT_BY_10', 'MATH.G2.NUMBER.MULTIPLICATION', 'mathematics', 2, 'Multiply 1-digit numbers by 10', ARRAY['MATH.G2.NUMBER.MULTIPLICATION.d']::text[], 'The child multiplies a 1-digit number by 10 (7 x 10 = 70) as that many tens, with bundles of ten or ten-shilling coins.', '["times 10","bundles of ten","ten-shilling coins","multiples of 10"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_MULTIPLY_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SHARING_2', 'MATH.G2.NUMBER.DIVISION', 'mathematics', 2, 'Represent division as equal sharing up to 20 by 2', ARRAY['MATH.G2.NUMBER.DIVISION.a']::text[], 'The child shares up to 20 objects equally between 2 by giving one at a time, says how many each gets, and says the sharing is fair only when both have the same.', '["share between two","how many each","is the sharing fair","draw the sharing"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G2_DIVISION_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3', 'MATH.G2.NUMBER.DIVISION', 'mathematics', 2, 'Represent division as equal grouping up to 25 by 3', ARRAY['MATH.G2.NUMBER.DIVISION.b']::text[], 'The child puts up to 25 objects into groups of 3 (or another given size), counts how many groups are made, and tells grouping (how many groups) from sharing (how many in each).', '["how many groups of 3","make groups and count","a bench or table story","draw the groups"]'::jsonb, '["representation","procedure"]'::jsonb, ARRAY['G2_DIVISION_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SIGN', 'MATH.G2.NUMBER.DIVISION', 'mathematics', 2, 'Use the ÷ sign in writing division statements', ARRAY['MATH.G2.NUMBER.DIVISION.c']::text[], 'The child writes a sharing or grouping as a division statement (12 ÷ 3 = 4), with the number shared first, and reads ÷ as ''shared by'' or ''divided by''.', '["write the division","read the division","match a picture to a division","fill the missing number"]'::jsonb, '["representation"]'::jsonb, ARRAY['G2_DIVISION_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_BY_4_5', 'MATH.G2.NUMBER.DIVISION', 'mathematics', 2, 'Divide numbers up to 25 by 4 and 5 without a remainder', ARRAY['MATH.G2.NUMBER.DIVISION.d']::text[], 'The child divides numbers up to 25 by 4 or 5 where it goes exactly (20 ÷ 4 = 5; 25 ÷ 5 = 5), by grouping objects or counting in fours and fives.', '["division fact","groups of 4 or 5","a sharing story","count in fives"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_DIVISION_INTRO']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE', 'MATH.G2.NUMBER.FRACTIONS', 'mathematics', 2, 'Identify a half as part of a whole', ARRAY['MATH.G2.NUMBER.FRACTIONS.a']::text[], 'The child folds or cuts a circle or rectangle into 2 equal parts, names one part as a half, writes it 1/2, and says two unequal parts are not halves.', '["which shows a half","shade a half","are these halves","write a half"]'::jsonb, '["recall","representation"]'::jsonb, ARRAY['G2_FRACTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE', 'MATH.G2.NUMBER.FRACTIONS', 'mathematics', 2, 'Identify a quarter as part of a whole', ARRAY['MATH.G2.NUMBER.FRACTIONS.b']::text[], 'The child folds a circle or rectangle into 4 equal parts, names one part as a quarter, writes it 1/4, and knows two quarters make a half.', '["which shows a quarter","shade a quarter","how many quarters make a whole","write a quarter"]'::jsonb, '["recall","representation"]'::jsonb, ARRAY['G2_FRACTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.USE_FRACTIONS', 'MATH.G2.NUMBER.FRACTIONS', 'mathematics', 2, 'Use halves and quarters in day-to-day activities', ARRAY['MATH.G2.NUMBER.FRACTIONS.c']::text[], 'The child uses halves and quarters in everyday situations: half of a chapati, half of a group of 8 mangoes is 4, a quarter of an orange, and says which is bigger, a half or a quarter of the same thing.', '["half of a group","share a chapati","which is bigger, a half or a quarter","how many quarters"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G2_FRACTIONS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.LENGTH.MEASURE_FIXED_UNITS', 'MATH.G2.MEASUR.LENGTH', 'mathematics', 2, 'Measure length using fixed units', ARRAY['MATH.G2.MEASUR.LENGTH.a']::text[], 'The child measures a length by laying sticks of the same length end to end with no gaps or overlaps, counts them, and says that the same object measured with a longer stick gives a smaller count.', '["how many sticks long","which measure is correct","why are the counts different","longer unit, fewer units"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G2_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.LENGTH.KNOW_METRE', 'MATH.G2.MEASUR.LENGTH', 'mathematics', 2, 'Identify the metre as a unit of measuring length', ARRAY['MATH.G2.MEASUR.LENGTH.b']::text[], 'The child knows the metre as the standard unit for length, recognises a metre stick, names everyday things about 1 metre long (a big step, a door''s width), and writes m.', '["which is about a metre","what unit is a metre","the short way to write metre","more or less than a metre"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.LENGTH.MEASURE_IN_METRES', 'MATH.G2.MEASUR.LENGTH', 'mathematics', 2, 'Measure length in metres', ARRAY['MATH.G2.MEASUR.LENGTH.c']::text[], 'The child measures lengths in whole metres with a metre stick (the classroom, the corridor), laying it end to end, and records the result with m.', '["how many metres long","read the metre sticks in a picture","record with m","which is longer in metres"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_LENGTH']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MASS.MEASURE_FIXED_MASS', 'MATH.G2.MEASUR.MASS', 'mathematics', 2, 'Measure mass using fixed units', ARRAY['MATH.G2.MEASUR.MASS.a']::text[], 'The child balances an object on a beam balance against items of the same mass (bottle tops, stones of one size), counts them when the beam is level, and says a heavier unit gives a smaller count.', '["how many bottle tops balance it","which side is heavier","read the balance picture","heavier unit, fewer units"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G2_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MASS.KNOW_KILOGRAM', 'MATH.G2.MEASUR.MASS', 'mathematics', 2, 'Identify the kilogram as a unit of measuring mass', ARRAY['MATH.G2.MEASUR.MASS.b']::text[], 'The child knows the kilogram as the standard unit for mass, recognises things sold by the kilogram (sugar, flour, maize), feels about how heavy 1 kg is, and writes kg.', '["which is about 1 kg","what is sold in kilograms","the short way to write kilogram","heavier or lighter than 1 kg"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MASS.MEASURE_IN_KG', 'MATH.G2.MEASUR.MASS', 'mathematics', 2, 'Measure mass of different objects in kilograms', ARRAY['MATH.G2.MEASUR.MASS.c']::text[], 'The child balances an object against 1 kg masses until level, counts the kilograms, and records the mass with kg.', '["how many kilograms","read the balance","record with kg","which is heavier in kg"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_MASS']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.CAPACITY.MEASURE_FIXED_CAPACITY', 'MATH.G2.MEASUR.CAPACITY', 'mathematics', 2, 'Measure capacity using fixed units', ARRAY['MATH.G2.MEASUR.CAPACITY.a']::text[], 'The child fills a container using a small container of a fixed size (a cup), counts the full cups, and says containers of different shapes can hold the same, and that a bigger cup gives a smaller count.', '["how many cups fill it","which holds more","same capacity, different shape","bigger cup, fewer cups"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G2_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.CAPACITY.KNOW_LITRE', 'MATH.G2.MEASUR.CAPACITY', 'mathematics', 2, 'Identify the litre as a unit of measuring capacity', ARRAY['MATH.G2.MEASUR.CAPACITY.b']::text[], 'The child knows the litre as the standard unit for capacity, recognises 1-litre bottles and packets (milk, water, oil), names containers that hold more or less than 1 litre, and writes l.', '["which holds about 1 litre","what is sold in litres","the short way to write litre","more or less than 1 litre"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.CAPACITY.MEASURE_IN_LITRES', 'MATH.G2.MEASUR.CAPACITY', 'mathematics', 2, 'Measure capacity in litres', ARRAY['MATH.G2.MEASUR.CAPACITY.c']::text[], 'The child fills a big container with a 1-litre container (or pours it out into one), counts the full litres, and records the capacity with l; finds how many buckets of a given number of litres fill a drum.', '["how many litres","how many full litre fills","record with l","how many buckets fill it"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_CAPACITY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.MONTHS_OCCASIONS', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Relate the months of the year to special occasions', ARRAY['MATH.G2.MEASUR.TIME.a']::text[], 'The child names the months of the year in order and links special occasions to their months (Christmas in December, Madaraka Day in June, Jamhuri Day in December, school opening in January), and says which month comes before or after another.', '["which month is this occasion in","the month after","the month before","put months in order"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.DAYS_IN_MONTHS', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Recite the number of days in each month of the year', ARRAY['MATH.G2.MEASUR.TIME.b']::text[], 'The child says how many days each month has (30 for April, June, September, November; 31 for the others; February 28, or 29 in a leap year), using a rhyme or the knuckle method.', '["how many days in this month","which months have 30 days","which month is shortest","the knuckle method"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.READ_CALENDAR', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Read the calendar in terms of day and date', ARRAY['MATH.G2.MEASUR.TIME.c']::text[], 'The child reads a calendar page to say the day of a given date (the 14th is a Thursday) and the date of a given day, and writes a date (Tuesday, 3rd March).', '["what day is this date","what date is this day","the date a week later","write the date"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.ARBITRARY_TIME', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Measure time using arbitrary units', ARRAY['MATH.G2.MEASUR.TIME.d']::text[], 'The child measures how long something takes with an arbitrary unit (claps, counts, drops of water) and relates the time of day to the length of a shadow (long in the morning and evening, short at midday).', '["how many claps did it take","which took longer","when is the shadow shortest","morning or midday from a shadow"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.CLOCK_HANDS', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Identify the minute hand and the hour hand on a clock face', ARRAY['MATH.G2.MEASUR.TIME.e']::text[], 'The child points to the long minute hand and the short hour hand on an analogue clock, and says which hand moves faster.', '["which is the hour hand","which is the minute hand","which hand moves faster","label the hands"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.READ_HOUR', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Read time by the hour from the clock face', ARRAY['MATH.G2.MEASUR.TIME.f']::text[], 'The child reads an analogue clock showing an o''clock time (the minute hand on 12, the hour hand on 4 is 4 o''clock) and matches clocks to o''clock times.', '["what time is it","which clock shows 7 o''clock","the time one hour later","match clock and time"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.TIME.WRITE_HOUR', 'MATH.G2.MEASUR.TIME', 'mathematics', 2, 'Write time by the hour shown by an analogue and a digital clock', ARRAY['MATH.G2.MEASUR.TIME.g']::text[], 'The child writes the o''clock time shown on an analogue clock (3 o''clock) and on a digital clock (3:00), and draws the hands for a given o''clock time.', '["write the time shown","write the digital time","draw the hands","match analogue and digital"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_TIME']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MONEY.IDENTIFY_MONEY_100', 'MATH.G2.MEASUR.MONEY', 'mathematics', 2, 'Identify Kenyan coins and notes up to sh. 100', ARRAY['MATH.G2.MEASUR.MONEY.a']::text[], 'The child names the Kenyan coins (sh. 1, 5, 10, 20) and notes (sh. 50, 100) by value, sorts them, and tells which is worth more by the number, not the size or the count.', '["name the coin or note","sort the money","which is worth more","coin or note"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MONEY.COUNT_10_20_COINS', 'MATH.G2.MEASUR.MONEY', 'mathematics', 2, 'Count sh. 10 and sh. 20 coins', ARRAY['MATH.G2.MEASUR.MONEY.b']::text[], 'The child counts a set of sh. 10 coins in tens and a set of sh. 20 coins in twenties, up to sh. 100, and writes the total with sh.', '["how much money in ten-shilling coins","count the twenty-shilling coins","how many coins make sh. 60","write the total"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MONEY.COUNT_50_100_NOTES', 'MATH.G2.MEASUR.MONEY', 'mathematics', 2, 'Count sh. 50 and sh. 100 notes', ARRAY['MATH.G2.MEASUR.MONEY.c']::text[], 'The child counts sh. 50 notes in fifties and sh. 100 notes in hundreds and says the total (two sh. 50 notes are sh. 100).', '["how much in fifty-shilling notes","count the hundred-shilling notes","how many fifties make a hundred","write the total"]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MONEY.ADD_MONEY_100', 'MATH.G2.MEASUR.MONEY', 'mathematics', 2, 'Add two denominations of money with a sum up to sh. 100', ARRAY['MATH.G2.MEASUR.MONEY.d']::text[], 'The child adds two amounts or two coins and notes (sh. 50 + sh. 20 = sh. 70; sh. 35 + sh. 40 = sh. 75), with a sum up to sh. 100, and writes sh.', '["add two amounts","total of two coins","how much for two items","column addition with sh."]'::jsonb, '["procedure"]'::jsonb, ARRAY['G2_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.MEASUR.MONEY.BUY_NO_BALANCE', 'MATH.G2.MEASUR.MONEY', 'mathematics', 2, 'Use money to buy up to 3 items without balance', ARRAY['MATH.G2.MEASUR.MONEY.e']::text[], 'The child picks coins and notes that pay exactly for up to 3 items (total up to sh. 100) in a model shop, finds the total cost, and checks no change is needed.', '["total cost of the items","which coins pay exactly","can you buy these with this money","role play at the shop"]'::jsonb, '["procedure","reasoning"]'::jsonb, ARRAY['G2_MONEY']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.GEOMET.LINES.STRAIGHT_LINES', 'MATH.G2.GEOMET.LINES', 'mathematics', 2, 'Model and draw straight lines', ARRAY['MATH.G2.GEOMET.LINES.a', 'MATH.G2.GEOMET.LINES.b']::text[], 'The child picks out straight lines in pictures and objects (the edge of a ruler, a door), models them with sticks or a stretched string, and draws them with a ruler, held upright, flat or slanting.', '["which line is straight","draw a straight line","is the edge straight or curved","straight lines in a picture"]'::jsonb, '["recall","representation"]'::jsonb, ARRAY['G2_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.GEOMET.LINES.CURVED_LINES', 'MATH.G2.GEOMET.LINES', 'mathematics', 2, 'Model and draw curved lines', ARRAY['MATH.G2.GEOMET.LINES.c', 'MATH.G2.GEOMET.LINES.d']::text[], 'The child picks out curved lines in pictures and objects (the edge of a plate, a rainbow), models them with string or clay, and draws them freehand.', '["which line is curved","draw a curved line","is the edge straight or curved","curved lines in a picture"]'::jsonb, '["recall","representation"]'::jsonb, ARRAY['G2_LINES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.GEOMET.SHAPES.NAME_SHAPES_ENV', 'MATH.G2.GEOMET.SHAPES', 'mathematics', 2, 'Identify different shapes in the environment', ARRAY['MATH.G2.GEOMET.SHAPES.a']::text[], 'The child names triangles, squares, rectangles, circles and ovals in objects and pictures (a window, a clock, an egg), in any position, and says the kind of lines each has (straight or curved).', '["name the shape of the object","which object is a circle","straight or curved sides","sort the shapes"]'::jsonb, '["recall"]'::jsonb, ARRAY['G2_SHAPES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.GEOMET.SHAPES.DRAW_SHAPES', 'MATH.G2.GEOMET.SHAPES', 'mathematics', 2, 'Draw shapes in different ways', ARRAY['MATH.G2.GEOMET.SHAPES.b']::text[], 'The child draws a triangle, a square, a circle and an oval, freehand and with a ruler or round objects, with the right number of sides.', '[]'::jsonb, '["representation"]'::jsonb, ARRAY['G2_SHAPES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
INSERT INTO public.curriculum_skills (code, substrand_code, subject_key, grade, name, outcome_codes, mastery, question_forms, thinking, horeb_skill_ids, status) VALUES ('MATH.G2.GEOMET.SHAPES.SHAPE_PATTERNS', 'MATH.G2.GEOMET.SHAPES', 'mathematics', 2, 'Draw and continue patterns involving different shapes', ARRAY['MATH.G2.GEOMET.SHAPES.c']::text[], 'The child finds the part of a shape pattern that repeats (circle, triangle, triangle), says or draws what comes next, and makes a pattern of their own.', '["what comes next","what is missing","which part repeats","make a pattern"]'::jsonb, '["reasoning"]'::jsonb, ARRAY['G2_SHAPES']::text[], 'proposed') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, outcome_codes = EXCLUDED.outcome_codes, mastery = EXCLUDED.mastery, question_forms = EXCLUDED.question_forms, thinking = EXCLUDED.thinking, horeb_skill_ids = EXCLUDED.horeb_skill_ids, updated_at = now() WHERE public.curriculum_skills.status = 'proposed';
