INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100.M_ID_REVERSED_DIGITS', 'MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100', 'Reads or picks a number with its digits reversed, as 61 for 16.', '{"question":"Which card shows sixteen: 16 or 61?","wrong_answer":"61","correct_answer":"16"}'::jsonb, 'Hears ''six'' first in sixteen and looks for the 6 first.', 'The answer 61 as a wrong option, with a reason that names the idea.', 'Sixteen is ten and six: the 1 for the ten comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100.M_ID_TEEN_TY', 'MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100', 'Mixes teen and ty numbers, picking 40 for fourteen.', '{"question":"Point to fourteen: 14 or 40?","wrong_answer":"40","correct_answer":"14"}'::jsonb, 'The words sound alike.', 'The answer 40 as a wrong option, with a reason that names the idea.', 'Fourteen ends in -teen and has 1 ten; forty has 4 tens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100.M_ID_100_AS_10', 'MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100', 'Reads 100 as ten or ''one zero zero''.', '{"question":"Read the number 100.","wrong_answer":"ten","correct_answer":"one hundred"}'::jsonb, 'Has not met three-digit numbers.', 'The answer ten as a wrong option, with a reason that names the idea.', 'Count ten bundles of ten: one hundred.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100.M_ID_CHART_ROW_SLIP', 'MATH.G2.NUMBER.NUMBER_CONCEPT.IDENTIFY_1_100', 'On a hundred chart, finds the number one row off.', '{"question":"On a hundred chart, which number is just below 34?","wrong_answer":"35","correct_answer":"44"}'::jsonb, 'Moves along the row instead of down.', 'The answer 35 as a wrong option, with a reason that names the idea.', 'Down a column adds ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100.M_REP_COUNTS_BUNDLES_AS_ONES', 'MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100', 'Counts each bundle of ten as one.', '{"question":"3 bundles of 10 sticks and 4 loose sticks. How many sticks?","wrong_answer":"7","correct_answer":"34"}'::jsonb, 'Counts objects, not what they hold.', 'The answer 7 as a wrong option, with a reason that names the idea.', 'Open a bundle and count: it is ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100.M_REP_ONES_TENS_SWAP', 'MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100', 'Writes the loose sticks as tens and the bundles as ones.', '{"question":"2 bundles of ten and 6 loose sticks. What number?","wrong_answer":"62","correct_answer":"26"}'::jsonb, 'Writes the numbers in the order seen.', 'The answer 62 as a wrong option, with a reason that names the idea.', 'Bundles are tens: write them first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100.M_REP_NOT_GROUPED', 'MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100', 'Counts a big collection one by one and loses count instead of making tens.', '{"question":"Count 47 bottle tops.","wrong_answer":"45","correct_answer":"47"}'::jsonb, 'Counts in ones without grouping.', 'The answer 45 as a wrong option, with a reason that names the idea.', 'Make heaps of ten, then count the heaps and the rest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100.M_REP_EXTRA_ZERO', 'MATH.G2.NUMBER.NUMBER_CONCEPT.REPRESENT_OBJECTS_100', 'Writes 3 tens and 5 ones as 305.', '{"question":"3 bundles of ten and 5 loose sticks. Write the number.","wrong_answer":"305","correct_answer":"35"}'::jsonb, 'Writes 30 and 5 side by side.', 'The answer 305 as a wrong option, with a reason that names the idea.', 'Tens and ones make a 2-digit number.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100.M_CF_DECADE_SKIP', 'MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100', 'After a number ending in 9, says the wrong ten, as 29, 20 or 29, 40.', '{"question":"Count on: 27, 28, 29, __","wrong_answer":"20","correct_answer":"30"}'::jsonb, 'Does not know which ten comes next.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'On a hundred chart, the next row starts the next ten.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100.M_CF_TEN_TEN', 'MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100', 'Counts past a ten as ''twenty-nine, twenty-ten''.', '{"question":"What comes after 39?","wrong_answer":"thirty-ten","correct_answer":"forty"}'::jsonb, 'Keeps saying the tens word and adds ten.', 'The answer thirty-ten as a wrong option, with a reason that names the idea.', 'Ten ones make a new ten: forty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100.M_CF_99_TO_1000', 'MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100', 'Says 1000 or 910 after 99.', '{"question":"What comes after 99?","wrong_answer":"1000","correct_answer":"100"}'::jsonb, 'Adds a zero or writes 9 and 10.', 'The answer 1000 as a wrong option, with a reason that names the idea.', 'Ten tens make a hundred: 100.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100.M_CF_COUNTS_START', 'MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_FORWARD_100', 'When counting on, says the starting number as one.', '{"question":"Count on 3 from 46. Where do you stop?","wrong_answer":"48","correct_answer":"49"}'::jsonb, 'Counts the start number.', 'The answer 48 as a wrong option, with a reason that names the idea.', 'Put a finger on 46 and say one on 47.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_BACK_50.M_CB_DECADE_BACK', 'MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_BACK_50', 'Counting back past a ten, says the wrong number, as 31, 30, 20.', '{"question":"Count back: 32, 31, 30, __","wrong_answer":"20","correct_answer":"29"}'::jsonb, 'Jumps a whole ten.', 'The answer 20 as a wrong option, with a reason that names the idea.', 'Count back on a number line one step at a time.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_BACK_50.M_CB_GOES_FORWARD', 'MATH.G2.NUMBER.WHOLE_NUMBERS.COUNT_BACK_50', 'Counts forward when asked to count back.', '{"question":"Count back from 45: 45, 44, __","wrong_answer":"45","correct_answer":"43"}'::jsonb, 'Treats counting as going up.', 'The answer 45 as a wrong option, with a reason that names the idea.', 'Walk backwards on a number line.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
