INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.MULTIPLICATION.MULT_BY_10.M_M102_COUNT_SLIP', 'MATH.G2.NUMBER.MULTIPLICATION.MULT_BY_10', 'Counts in tens one step too many.', '{"question":"How much is 4 ten-shilling coins?","wrong_answer":"sh. 50","correct_answer":"sh. 40"}'::jsonb, 'Starts the count at ten for no coin.', 'The answer sh. 50 as a wrong option, with a reason that names the idea.', 'Touch each coin: 10, 20, 30, 40.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SHARING_2.M_DS_UNEQUAL', 'MATH.G2.NUMBER.DIVISION.DIV_SHARING_2', 'Shares so that one child gets more and calls it fair.', '{"question":"Share 10 sweets between 2 children: 6 and 4. Is it fair?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Thinks sharing means giving some to each.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Give one at a time to each child until none are left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SHARING_2.M_DS_GIVES_TOTAL', 'MATH.G2.NUMBER.DIVISION.DIV_SHARING_2', 'Gives the total as what each gets.', '{"question":"Share 12 mangoes between 2. How many each?","wrong_answer":"12","correct_answer":"6"}'::jsonb, 'Answers with the number in the story.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Act it out: one for you, one for me.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SHARING_2.M_DS_TAKES_TWO', 'MATH.G2.NUMBER.DIVISION.DIV_SHARING_2', 'Takes away 2 instead of sharing between 2.', '{"question":"Share 14 pencils between 2. How many each?","wrong_answer":"12","correct_answer":"7"}'::jsonb, 'Sees 2 and subtracts.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Share one by one into 2 piles.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SHARING_2.M_DS_COUNTS_ROUNDS_WRONG', 'MATH.G2.NUMBER.DIVISION.DIV_SHARING_2', 'Loses count of the rounds of giving.', '{"question":"Share 16 between 2. How many each?","wrong_answer":"9","correct_answer":"8"}'::jsonb, 'Counts unevenly while sharing.', 'The answer 9 as a wrong option, with a reason that names the idea.', 'Count both piles at the end.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3.M_DIV2_SUBTRACTS_ONCE', 'MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3', 'Takes one group away and gives what is left.', '{"question":"15 learners sit 3 to a bench. How many benches?","wrong_answer":"12","correct_answer":"5"}'::jsonb, 'Does one take-away and stops.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Keep taking 3 until none are left; count the benches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3.M_DIV2_GIVES_GROUP_SIZE', 'MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3', 'Gives the size of a group instead of the number of groups.', '{"question":"18 learners sit 3 to a bench. How many benches?","wrong_answer":"3","correct_answer":"6"}'::jsonb, 'Repeats a number in the story.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Ask: how many in each, and how many groups?', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3.M_DIV2_ONE_EXTRA', 'MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3', 'Counts one group too many.', '{"question":"21 in groups of 3. How many groups?","wrong_answer":"8","correct_answer":"7"}'::jsonb, 'Counts an empty group.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Ring each group and count the rings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3.M_DIV2_SHARE_GROUP_CONFUSED', 'MATH.G2.NUMBER.DIVISION.DIV_GROUPING_3', 'Shares into 3 groups when asked for groups of 3.', '{"question":"Put 12 counters in groups of 3. How many groups?","wrong_answer":"3","correct_answer":"4"}'::jsonb, 'Mixes ''into 3 groups'' and ''groups of 3''.', 'The answer 3 as a wrong option, with a reason that names the idea.', 'Groups of 3 means each group has 3.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SIGN.M_DSIGN_ORDER', 'MATH.G2.NUMBER.DIVISION.DIV_SIGN', 'Writes the smaller number first, as 3 ÷ 12.', '{"question":"Write 12 shared into 3 equal groups as a division.","wrong_answer":"3 ÷ 12 = 4","correct_answer":"12 ÷ 3 = 4"}'::jsonb, 'Writes the numbers in any order.', 'The answer 3 ÷ 12 = 4 as a wrong option, with a reason that names the idea.', 'The number being shared comes first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SIGN.M_DSIGN_USES_MINUS', 'MATH.G2.NUMBER.DIVISION.DIV_SIGN', 'Writes a subtraction for a sharing.', '{"question":"Write 10 shared by 2 equals 5 as a sentence.","wrong_answer":"10 - 2 = 5","correct_answer":"10 ÷ 2 = 5"}'::jsonb, 'Thinks sharing is taking away.', 'The answer 10 - 2 = 5 as a wrong option, with a reason that names the idea.', 'Use the ÷ sign for sharing.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SIGN.M_DSIGN_ANSWER_PLACE', 'MATH.G2.NUMBER.DIVISION.DIV_SIGN', 'Puts the answer in the wrong place, as 5 ÷ 2 = 10.', '{"question":"Write: 10 shared by 2 gives 5.","wrong_answer":"5 ÷ 2 = 10","correct_answer":"10 ÷ 2 = 5"}'::jsonb, 'Does not know which number goes after =.', 'The answer 5 ÷ 2 = 10 as a wrong option, with a reason that names the idea.', 'The answer goes after the = sign.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_SIGN.M_DSIGN_READS_AS_PLUS', 'MATH.G2.NUMBER.DIVISION.DIV_SIGN', 'Reads ÷ as plus or times.', '{"question":"What is 8 ÷ 2?","wrong_answer":"10","correct_answer":"4"}'::jsonb, 'Mixes the signs.', 'The answer 10 as a wrong option, with a reason that names the idea.', '÷ means share by.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_BY_4_5.M_D45_GIVES_DIVISOR', 'MATH.G2.NUMBER.DIVISION.DIV_BY_4_5', 'Gives the divisor as the answer.', '{"question":"20 ÷ 4","wrong_answer":"4","correct_answer":"5"}'::jsonb, 'Repeats a number.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Make groups of 4 and count them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_BY_4_5.M_D45_SKIP_SLIP', 'MATH.G2.NUMBER.DIVISION.DIV_BY_4_5', 'Counts in fives one step too many or too few.', '{"question":"25 ÷ 5","wrong_answer":"4","correct_answer":"5"}'::jsonb, 'Loses count while skip counting.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Fingers: 5, 10, 15, 20, 25.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_BY_4_5.M_D45_SUBTRACTS', 'MATH.G2.NUMBER.DIVISION.DIV_BY_4_5', 'Takes away the divisor once.', '{"question":"16 ÷ 4","wrong_answer":"12","correct_answer":"4"}'::jsonb, 'Sees one take-away.', 'The answer 12 as a wrong option, with a reason that names the idea.', 'Keep taking 4 until none are left.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.DIVISION.DIV_BY_4_5.M_D45_MULTIPLIES', 'MATH.G2.NUMBER.DIVISION.DIV_BY_4_5', 'Multiplies instead of dividing.', '{"question":"20 ÷ 5","wrong_answer":"100","correct_answer":"4"}'::jsonb, 'Mixes the signs.', 'The answer 100 as a wrong option, with a reason that names the idea.', 'Dividing shares out, so the answer is smaller.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE.M_HALF_UNEQUAL', 'MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE', 'Calls either of two unequal pieces a half.', '{"question":"A mandazi is broken into a big piece and a small piece. Is each a half?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Thinks half means one of two pieces.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Fold paper: halves match exactly.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE.M_HALF_BIGGER_HALF', 'MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE', 'Talks of ''the bigger half''.', '{"question":"Wanjiku says she has the bigger half. Can one half be bigger?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Uses ''half'' for any part, as in everyday speech.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Two halves of the same thing are always the same size.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE.M_HALF_WRITES_2_1', 'MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE', 'Writes a half as 2/1 or 12.', '{"question":"Write a half.","wrong_answer":"2/1","correct_answer":"1/2"}'::jsonb, 'Does not know which number goes where.', 'The answer 2/1 as a wrong option, with a reason that names the idea.', '1 part out of 2 equal parts: 1 on top, 2 below.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE.M_HALF_WRONG_FOLD', 'MATH.G2.NUMBER.FRACTIONS.HALF_OF_WHOLE', 'Folds a shape so the parts do not match and calls them halves.', '{"question":"A rectangle is folded corner to a middle point. Are the parts halves?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Folds without matching the edges.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Match the edges before you press the fold.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE.M_QTR_FOUR_UNEQUAL', 'MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE', 'Calls any of four unequal parts a quarter.', '{"question":"A circle is cut into 4 pieces of different sizes. Is one piece a quarter?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Thinks a quarter is one of four pieces.', 'The answer yes as a wrong option, with a reason that names the idea.', 'Fold in half, then in half again: the parts match.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE.M_QTR_BIGGER_THAN_HALF', 'MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE', 'Thinks a quarter is bigger than a half because 4 is bigger than 2.', '{"question":"Which is bigger: a half or a quarter of the same orange?","wrong_answer":"a quarter","correct_answer":"a half"}'::jsonb, 'Compares the numbers 4 and 2.', 'The answer a quarter as a wrong option, with a reason that names the idea.', 'Cut two same oranges into 2 and 4.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE.M_QTR_THREE_PARTS', 'MATH.G2.NUMBER.FRACTIONS.QUARTER_OF_WHOLE', 'Calls one of three equal parts a quarter.', '{"question":"A bar is cut into 3 equal parts. Is one part a quarter?","wrong_answer":"yes","correct_answer":"no"}'::jsonb, 'Thinks quarter means a small part.', 'The answer yes as a wrong option, with a reason that names the idea.', 'A quarter is one of 4 equal parts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
