INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.USE_FRACTIONS.M_FRUSE_UNEQUAL_HALVES', 'MATH.G2.NUMBER.FRACTIONS.USE_FRACTIONS', 'Shares so that one half has one more.', '{"question":"Half of 14 bananas?","wrong_answer":"8","correct_answer":"7"}'::jsonb, 'Shares unevenly.', 'The answer 8 as a wrong option, with a reason that names the idea.', 'Check both groups are equal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('MATH.G2.NUMBER.FRACTIONS.USE_FRACTIONS.M_FRUSE_QUARTER_AS_FOUR', 'MATH.G2.NUMBER.FRACTIONS.USE_FRACTIONS', 'Gives 4 as a quarter of any group.', '{"question":"A quarter of 8 sweets?","wrong_answer":"4","correct_answer":"2"}'::jsonb, 'Sees 4 and writes it.', 'The answer 4 as a wrong option, with a reason that names the idea.', 'Share 8 into 4 equal groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
